#include <iostream>
#include <sstream>
#include <iomanip>
#include <cstring>

struct ClientRecord {
    int accountNumber{0};
    char lastName[15]{""};
    char firstName[10]{""};
    double balance{0.0};
};

void setRecord(std::iostream& stream, int id, const char* last, const char* first, double bal) {
    ClientRecord rec;
    rec.accountNumber = id;
    std::strncpy(rec.lastName, last, sizeof(rec.lastName) - 1);
    std::strncpy(rec.firstName, first, sizeof(rec.firstName) - 1);
    rec.balance = bal;

    std::streampos pos = static_cast<std::streamoff>((id - 1) * sizeof(ClientRecord));
    stream.seekp(pos);
    stream.write(reinterpret_cast<const char*>(&rec), sizeof(ClientRecord));
}

void updateRecord(std::iostream& stream, int id, double delta) {
    std::streampos pos = static_cast<std::streamoff>((id - 1) * sizeof(ClientRecord));
    stream.seekg(pos);
    ClientRecord rec;
    stream.read(reinterpret_cast<char*>(&rec), sizeof(ClientRecord));

    if (rec.accountNumber == 0) {
        std::cout << "Account #" << id << " is empty.\n";
        return;
    }
    rec.balance += delta;
    stream.seekp(pos);
    stream.write(reinterpret_cast<const char*>(&rec), sizeof(ClientRecord));
    std::cout << "Account #" << id << " updated. New balance: " 
              << std::fixed << std::setprecision(2) << rec.balance << "\n";
}

void deleteRecord(std::iostream& stream, int id) {
    std::streampos pos = static_cast<std::streamoff>((id - 1) * sizeof(ClientRecord));
    ClientRecord blankRecord;
    stream.seekp(pos);
    stream.write(reinterpret_cast<const char*>(&blankRecord), sizeof(ClientRecord));
    std::cout << "Account #" << id << " deleted.\n";
}

int main() {
    // Simulate random-access binary file in memory using std::stringstream
    std::stringstream file(std::ios::in | std::ios::out | std::ios::binary);
    ClientRecord blank;
    for (int i = 0; i < 5; ++i) {
        file.write(reinterpret_cast<const char*>(&blank), sizeof(ClientRecord));
    }

    setRecord(file, 2, "Barker", "Doug", 0.0);
    updateRecord(file, 2, 87.99);
    deleteRecord(file, 2);
    updateRecord(file, 2, 10.00);

    return 0;
}

#include <iostream>
#include <sstream>
#include <cstdint>
#include <string>

enum class DataType : uint8_t { INT = 1, STRING = 2 };

int main() {
    std::stringstream stream(std::ios::in | std::ios::out | std::ios::binary);

    // 1. Serialization: write type tag + payload
    DataType tagInt = DataType::INT;
    int32_t num = 42;
    stream.write(reinterpret_cast<const char*>(&tagInt), sizeof(tagInt));
    stream.write(reinterpret_cast<const char*>(&num), sizeof(num));

    DataType tagStr = DataType::STRING;
    std::string text = "ModernC++";
    uint32_t len = static_cast<uint32_t>(text.size());
    stream.write(reinterpret_cast<const char*>(&tagStr), sizeof(tagStr));
    stream.write(reinterpret_cast<const char*>(&len), sizeof(len));
    stream.write(text.data(), len);

    std::cout << "Bytes written (tellp): " << stream.tellp() << "\n";

    // 2. Reposition get pointer to beginning
    stream.seekg(0, std::ios::beg);
    std::cout << "Initial tellg: " << stream.tellg() << "\n";

    // 3. Deserialization: dynamically recreate objects based on type tags
    DataType currentTag;
    while (stream.read(reinterpret_cast<char*>(&currentTag), sizeof(currentTag))) {
        if (currentTag == DataType::INT) {
            int32_t val{0};
            stream.read(reinterpret_cast<char*>(&val), sizeof(val));
            std::cout << "Deserialized INT: " << val << "\n";
        } else if (currentTag == DataType::STRING) {
            uint32_t strLen{0};
            stream.read(reinterpret_cast<char*>(&strLen), sizeof(strLen));
            std::string s(strLen, '\0');
            stream.read(&s[0], strLen);
            std::cout << "Deserialized STRING: " << s << "\n";
        }
    }

    return 0;
}
